def as_of(reports, date):
    best = {}
    for ticker, period_end, published, value in reports:
        if published > date:
            continue
        key = (period_end, published)
        if ticker not in best or key > best[ticker][0]:
            best[ticker] = (key, value)
    return {t: v for t, (k, v) in best.items()}
